#pragma once

// Learned route-cut scores from the distilled set encoder, for the embedded
// planner: obstacle tokens (path frame position, radius, straight-line
// clearance and its time, obstacle count) pass through two self-attention
// layers; a cut is scored from its obstacle's token, the mean token, and the
// cut's direction and time. Same math as SetEncoderPolicy in
// include/continuous/engine/oneshot_policy.hpp, in fixed-size float code
// with int8 weights (one float scale per output row) compiled in
// (set_encoder_weights.hpp, generated by benchmarks/learning/compress_models.py).
// The score only orders route cuts; acceptance is always the checker.

#include <tinysdp_ct_embedded/set_encoder_weights.hpp>

#include <cmath>
#include <cstdint>
#include <limits>

namespace tinysdp_ct_embedded {

namespace detail {
// y = b + scale .* (q x), q row major (Rows x Cols).
template<int Rows, int Cols>
inline void linear_q8(const std::int8_t (&q)[Rows * Cols], const float (&scale)[Rows], const float (&b)[Rows],
                      const float* x, float* y, bool relu) {
    for (int r = 0; r < Rows; ++r) {
        const std::int8_t* row = q + r * Cols;
        float acc = 0;
        for (int c = 0; c < Cols; ++c) acc += float(row[c]) * x[c];
        const float v = b[r] + scale[r] * acc;
        y[r] = relu && v < 0.f ? 0.f : v;
    }
}
}  // namespace detail

template<int MaxN>
class SetEncoder {
public:
    static constexpr int W = set_encoder_weights::kWidth, H = set_encoder_weights::kHeads, Dh = W / H;
    static constexpr int kHidden = 64;

    // Encode the scene once per frame: spheres at plan time 0, 3D.
    template<class Sphere>
    void encode(const float* start, const float* goal, const Sphere* spheres, int n) {
        namespace w = set_encoder_weights;
        n_ = n < MaxN ? n : MaxN;
        float fwd[3], dist2 = 0, mid[3];
        for (int c = 0; c < 3; ++c) { fwd[c] = goal[c] - start[c]; dist2 += fwd[c] * fwd[c]; mid[c] = 0.5f * (start[c] + goal[c]); }
        const float length = std::fmax(1e-9f, 0.5f * std::sqrt(dist2));
        for (float& v : fwd) v /= 2 * length;
        frame(fwd);
        for (int k = 0; k < n_; ++k) {
            float best = std::numeric_limits<float>::infinity(), when = 0;
            for (int i = 0; i <= 200; ++i) {
                float d2 = 0;
                for (int c = 0; c < 3; ++c) {
                    const float q = start[c] + (i / 200.f) * (goal[c] - start[c]) - float(spheres[k].center[c]);
                    d2 += q * q;
                }
                const float d = std::sqrt(d2) - float(spheres[k].radius);
                if (d < best) { best = d; when = i / 200.f; }
            }
            float rel[3], token[7];
            for (int c = 0; c < 3; ++c) rel[c] = float(spheres[k].center[c]) - mid[c];
            token[0] = dot(rel, fwd) / length; token[1] = dot(rel, e1_) / length; token[2] = dot(rel, e2_) / length;
            token[3] = float(spheres[k].radius) / length; token[4] = best / length; token[5] = when; token[6] = n / 12.f;
            float hidden[W];
            detail::linear_q8<W, 7>(w::encoder_embed_0_weight_q, w::encoder_embed_0_weight_s, w::encoder_embed_0_bias, token, hidden, true);
            detail::linear_q8<W, W>(w::encoder_embed_2_weight_q, w::encoder_embed_2_weight_s, w::encoder_embed_2_bias, hidden, h_[k], false);
        }
        attention<0>();
        attention<1>();
        for (int c = 0; c < W; ++c) {
            float sum = 0;
            for (int k = 0; k < n_; ++k) sum += h_[k][c];
            pooled_[c] = n_ ? sum / n_ : 0.f;
        }
    }

    // Score of a cut on obstacle `o` (index into the encoded spheres) at
    // straight-path time `tau` in unit direction `u`: log P(certified) minus
    // predicted log cost excess.
    float score(int o, const float* u, float tau) const {
        namespace w = set_encoder_weights;
        float x[2 * W + 4], a[kHidden], b[kHidden], y[2];
        for (int c = 0; c < W; ++c) { x[c] = h_[o][c]; x[W + c] = pooled_[c]; }
        x[2 * W] = dot(u, e1_); x[2 * W + 1] = dot(u, e2_); x[2 * W + 2] = tau; x[2 * W + 3] = std::fabs(tau - 0.5f);
        detail::linear_q8<kHidden, 2 * W + 4>(w::head_0_weight_q, w::head_0_weight_s, w::head_0_bias, x, a, true);
        detail::linear_q8<kHidden, kHidden>(w::head_2_weight_q, w::head_2_weight_s, w::head_2_bias, a, b, true);
        detail::linear_q8<2, kHidden>(w::head_4_weight_q, w::head_4_weight_s, w::head_4_bias, b, y, false);
        const float logit = y[0];
        const float log_probability = logit >= 0.f ? -std::log1p(std::exp(-logit)) : logit - std::log1p(std::exp(logit));
        return log_probability - y[1];
    }

private:
    static float dot(const float* a, const float* b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }

    void frame(const float* f) {
        float ref[3] = {0, 0, 1};
        if (std::fabs(f[2]) >= 0.9f) { ref[1] = 1; ref[2] = 0; }
        e1_[0] = f[1] * ref[2] - f[2] * ref[1]; e1_[1] = f[2] * ref[0] - f[0] * ref[2]; e1_[2] = f[0] * ref[1] - f[1] * ref[0];
        const float n1 = std::sqrt(dot(e1_, e1_));
        for (float& v : e1_) v /= n1;
        e2_[0] = f[1] * e1_[2] - f[2] * e1_[1]; e2_[1] = f[2] * e1_[0] - f[0] * e1_[2]; e2_[2] = f[0] * e1_[1] - f[1] * e1_[0];
        const float n2 = std::sqrt(dot(e2_, e2_));
        for (float& v : e2_) v /= n2;
    }

    // h = LayerNorm(h + OutProj(MultiHeadAttention(h))), one head at a time
    // (K and V of one head live in k_/v_; Q rows are formed on the fly).
    template<int L>
    void attention() {
        namespace w = set_encoder_weights;
        const std::int8_t* in_q = L == 0 ? w::encoder_blocks_0_in_proj_weight_q : w::encoder_blocks_1_in_proj_weight_q;
        const float* in_s = L == 0 ? w::encoder_blocks_0_in_proj_weight_s : w::encoder_blocks_1_in_proj_weight_s;
        const float* in_b = L == 0 ? w::encoder_blocks_0_in_proj_bias : w::encoder_blocks_1_in_proj_bias;
        const auto project = [&](int row, const float* x) {   // row of the stacked (3W x W) in-projection
            const std::int8_t* q = in_q + row * W;
            float acc = 0;
            for (int c = 0; c < W; ++c) acc += float(q[c]) * x[c];
            return in_b[row] + in_s[row] * acc;
        };
        const float inv_sqrt = 1.f / std::sqrt(float(Dh));
        for (int head = 0; head < H; ++head) {
            for (int k = 0; k < n_; ++k)
                for (int d = 0; d < Dh; ++d) {
                    k_[k][d] = project(W + head * Dh + d, h_[k]);
                    v_[k][d] = project(2 * W + head * Dh + d, h_[k]);
                }
            for (int r = 0; r < n_; ++r) {
                float q[Dh], p[MaxN], top = -std::numeric_limits<float>::infinity(), sum = 0;
                for (int d = 0; d < Dh; ++d) q[d] = project(head * Dh + d, h_[r]);
                for (int k = 0; k < n_; ++k) {
                    float s = 0;
                    for (int d = 0; d < Dh; ++d) s += q[d] * k_[k][d];
                    p[k] = s * inv_sqrt;
                    if (p[k] > top) top = p[k];
                }
                for (int k = 0; k < n_; ++k) { p[k] = std::exp(p[k] - top); sum += p[k]; }
                for (int d = 0; d < Dh; ++d) {
                    float acc = 0;
                    for (int k = 0; k < n_; ++k) acc += p[k] * v_[k][d];
                    attended_[r][head * Dh + d] = acc / sum;
                }
            }
        }
        for (int r = 0; r < n_; ++r) {
            float y[W];
            if (L == 0) detail::linear_q8<W, W>(w::encoder_blocks_0_out_proj_weight_q, w::encoder_blocks_0_out_proj_weight_s, w::encoder_blocks_0_out_proj_bias, attended_[r], y, false);
            else detail::linear_q8<W, W>(w::encoder_blocks_1_out_proj_weight_q, w::encoder_blocks_1_out_proj_weight_s, w::encoder_blocks_1_out_proj_bias, attended_[r], y, false);
            float mean = 0, var = 0;
            for (int c = 0; c < W; ++c) { y[c] += h_[r][c]; mean += y[c]; }
            mean /= W;
            for (int c = 0; c < W; ++c) var += (y[c] - mean) * (y[c] - mean);
            const float inv = 1.f / std::sqrt(var / W + 1e-5f);
            const float* gamma = L == 0 ? w::encoder_norms_0_weight : w::encoder_norms_1_weight;
            const float* beta = L == 0 ? w::encoder_norms_0_bias : w::encoder_norms_1_bias;
            for (int c = 0; c < W; ++c) h_[r][c] = (y[c] - mean) * inv * gamma[c] + beta[c];
        }
    }

    float h_[MaxN][W] = {}, attended_[MaxN][W] = {}, k_[MaxN][Dh] = {}, v_[MaxN][Dh] = {};
    float pooled_[W] = {}, e1_[3] = {}, e2_[3] = {};
    int n_ = 0;
};

}  // namespace tinysdp_ct_embedded
